window.hbEngineRequestClose=async()=>{if(kiosk.enabled&&!operatorMenu&&!config.smoke&&!config.acceptance)return;if(kiosk.enabled)window.chrome?.webview?.postMessage('hbengine.operator.unlock');if(closed){if(closing)return;closing=true;try{await failureCleanup;await flushStorage();window.chrome?.webview?.postMessage('hbengine.close');}catch(error){closing=false;$('#error').textContent='게임 저장 실패: '+error.message;}return;}if(closing)return;closing=true;frameLoop.stop();try{while(busy)await new Promise(resolve=>setTimeout(resolve,10));await release('Stopped');closed=true;await flushStorage();window.chrome?.webview?.postMessage('hbengine.close');}catch(error){closing=false;closed=false;await fail(error);}};$('#quit').onclick=()=>window.hbEngineRequestClose();
try{const startup=await readAsset(session.startupScene);if(!validScene(startup))throw Error('시작 장면 검증 실패');renderer=await createGameRenderer(canvas,startup.runtime?.renderBackend,fail);await openScene(session.startupScene,startup);$('#loading').hidden=true;canvas.focus();last=performance.now();schedule();}catch(error){await fail(error);}
